// Validates that package-lock.json is reproducible on any end-user machine.
// Exit code 0 = usable lockfile, 1 = must be regenerated by the build script.
import fs from "node:fs";

const PUBLIC_HOST = "registry.npmjs.org";
const file = "package-lock.json";

if (!fs.existsSync(file)) {
  console.error("LOCK MISSING");
  process.exit(1);
}

let lock;
try {
  lock = JSON.parse(fs.readFileSync(file, "utf8"));
} catch {
  console.error("LOCK UNPARSABLE");
  process.exit(1);
}

const packages = lock.packages || {};
const problems = [];
for (const [name, meta] of Object.entries(packages)) {
  if (!name || meta.link) continue;
  // Packages bundled inside another tarball legitimately have no resolved URL.
  if (meta.inBundle) continue;
  const resolved = meta.resolved;
  if (!resolved) {
    if (name.includes("/node_modules/@emnapi/") || name.includes("wasm32-wasi/node_modules/")) continue;
    problems.push(`${name}: no download URL in lockfile`);
    continue;
  }
  if (!resolved.startsWith("http")) continue;
  const host = new URL(resolved).host;
  if (host !== PUBLIC_HOST) problems.push(`${name}: private registry host ${host}`);
}

if (problems.length) {
  console.error(`LOCK INVALID (${problems.length} entries)`);
  for (const problem of problems.slice(0, 10)) console.error(" - " + problem);
  process.exit(1);
}

console.log("LOCK OK");
